import Image from "next/image";

export default function TrailService() {
  return (
    <section className="bg-[#f5f5f5] py-20 px-4">
      <div
        className="max-w-[1200px] mx-auto
        flex flex-col md:flex-row items-center
        gap-12 md:gap-20
        bg-[#efaa73] rounded-3xl shadow-lg
        px-6 md:px-16 py-12 md:py-20"
      >
        {/* LEFT CONTENT */}
        <div className="flex-1 flex flex-col justify-center items-center md:items-start text-center md:text-left">
          
          <h1 className="text-3xl md:text-4xl lg:text-5xl font-semibold text-[#5a0d1f] leading-tight mb-6 max-w-[600px]">
            Free Trial Makeup Sessions
          </h1>

          <p className="text-base md:text-lg lg:text-xl text-[#2e2e2e] leading-relaxed mb-8 max-w-[550px]">
            We offer professional free trial makeup sessions to help you find
            the perfect look for your special day. Work with our experienced
            artists to enhance your natural beauty.
          </p>

          <button
            className="bg-gradient-to-r from-purple-700 to-pink-600
            hover:scale-105 hover:shadow-lg
            text-white px-7 py-3 rounded-lg
            text-base font-medium transition duration-300"
          >
            Book Now
          </button>
        </div>

        {/* RIGHT IMAGE */}
        <div className="flex-1 flex justify-center md:justify-end">
          <div className="bg-white p-4 md:p-5 rounded-2xl shadow-lg">
            <Image
              src="https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199688/home-trail_tqf8fz.webp"
              alt="Trial Makeup"
              width={360}
              height={480}
              className="rounded-xl object-cover"
              priority
            />
          </div>
        </div>
      </div>
    </section>
  );
}